from lib89 import *
def B(ch,tn,*a,**k): build('science',ch,tn,*a,**k)
B(1,'Science beyond the classroom','Entering the world of secondary science','How does a mask really work?',
 "During the pandemic we all wore masks. To understand why a mask works you need physics for moving particles and static electricity, chemistry for polymer fibres, biology for the size of viruses and mathematics for airflow. Real problems need all of science together.",
 [("In Grade 9 we enter secondary science, where ideas from physics, chemistry, biology and mathematics are used together to solve real problems.","interdisciplinary"),
  ("A surgical mask is a good example. Particle motion and electrostatic attraction (physics), properties of polymer fibres (chemistry), the size and behaviour of viruses (biology) and modelling airflow and filtration (mathematics) all explain how it works.","a mask uses all branches"),
  ("Science is not only a collection of facts, equations or experiments. It is a human activity shaped by curiosity, creativity, collaboration and careful questioning.","science is a human activity"),
  ("It grows as people ask questions, test ideas, share results and learn from mistakes.","ask, test, share, learn"),
  ("Science has developed over time through the work of many people across different cultures and generations.","many people, many cultures"),
  ("Every chapter has activities, projects and thinking questions, so we learn by doing and not only by reading.","learn by doing"),
  ("Even if you do not study science after Grade 10, scientific thinking helps you understand technology, judge information critically and make good decisions.","scientific thinking"),
  ("So we begin this year with an open mind, ready to question, measure and test ideas.","open mind")],
 ("Name the branches of science needed to explain why a mask stops a virus.",[("Particle motion and static attraction belong to physics.","Fibres attract and stop small particles."),("The polymer fibres belong to chemistry and the virus size to biology.","Material and organism."),("Airflow and filtration efficiency use mathematics.","All four branches work together.")]),
 ("Why do real problems need several branches of science?",["A mask example uses physics, chemistry, biology and maths","Science is a human activity","Scientific thinking helps in everyday life"],["Thinking science is only a list of facts"]),
 ["Real problems use ideas from many branches of science.","Science is a human activity built on curiosity, questioning and collaboration.","It develops over generations and across cultures.","Scientific thinking helps in daily life."],
 [mcq("s1-1",1,"Which branch explains the electrostatic attraction in a mask?","Physics",["Geography","Civics"],"Electrostatics belongs to physics."),
  tf("s1-2",1,"Science is only a collection of facts and equations.",False,"It is a human activity of questioning, testing and sharing."),
  mcq("s1-3",1,"Properties of polymer fibres in a mask come under","Chemistry",["Biology","History"],"Polymers and materials are studied in chemistry."),
  mcq("s1-4",2,"Studying the size and behaviour of viruses is part of","Biology",["Physics","Mathematics"],"Viruses are living-world topics."),
  mcq("s1-5",2,"Modelling airflow and filtration efficiency needs","Mathematics",["Poetry","Cookery"],"Mathematical models describe airflow."),
  tf("s1-6",2,"Science develops through the work of many people over time.",True,"Many individuals across cultures and generations contributed."),
  short("s1-7",3,"Name one quality that shapes science (curiosity, creativity or collaboration).",["curiosity","creativity","collaboration"],"All three shape science."),
  tf("s1-8",3,"Scientific thinking is useful only to scientists.",False,"It helps everyone evaluate information and make decisions.")])
B(2,'The cell and cell division','The cell: structure, division and cell theory','The brick of life',
 "A house is built from bricks. Your body is built from cells, trillions of them, and each cell is alive. From a tiny bacterium to a giant tree, everything living is made of cells.",
 [("The cell is the basic structural and functional unit of life. Most cells are too small to see, so we study them with microscopes.","cell"),
  ("The human eye cannot separate two points closer than about 0.1 mm, so most plant and animal cells, which are much smaller, need a microscope.","microscope"),
  ("The cell membrane is made of proteins and lipids. It controls what enters and leaves, and its mosaic-like arrangement of molecules is why it is called the fluid mosaic model.","cell membrane"),
  ("Cells with no true nucleus are called prokaryotic cells. Their genetic material lies in a region called the nucleoid, while eukaryotic cells have a nucleus.","prokaryotic and eukaryotic"),
  ("Plant cells also have a cell wall and plastids. Coloured plastids are called chromoplasts, from the Greek chroma, colour.","plastids"),
  ("Cells grow and divide to replace old, dead or damaged cells. This is how a cut heals and how hair grows back.","cell division"),
  ("Cell division is the process by which new cells are formed from existing cells. The body grows by more cells, not just bigger cells.","growth by division"),
  ("Cell theory says all organisms are made of cells (Schleiden, 1838 for plants and Schwann, 1839 for animals), and, as Virchow added in 1855, all cells come from pre-existing cells.","cell theory")],
 ("Why can a bacterium be called a prokaryote while an onion cell is a eukaryote?",[("A bacterium has no true nucleus; its DNA is in the nucleoid.","Look for a nucleus."),("An onion cell has a nucleus enclosed by a membrane.","True nucleus present."),("So bacteria are prokaryotes and onion cells are eukaryotes.","Classify by nucleus.")]),
 ("State the cell theory and one difference between prokaryotic and eukaryotic cells.",["All organisms are made of cells","Cells arise from existing cells","Nucleus present or absent"],["Thinking all cells have a cell wall"]),
 ["The cell is the unit of life.","Prokaryotic cells have no true nucleus; eukaryotic cells do.","Cells divide to repair and to grow.","Cell theory unifies biology."],
 [mcq("s2-1",1,"The cell membrane is made of","proteins and lipids",["cellulose only","starch"],"Cell membranes are made of proteins and lipids."),
  mcq("s2-2",1,"Cells without a true nucleus are","prokaryotic",["eukaryotic","only plant cells"],"Their DNA lies in the nucleoid."),
  tf("s2-3",1,"All plants are made of cells.",True,"Schleiden reported this in 1838."),
  mcq("s2-4",2,"Who reported that all animals are made of cells?","Schwann",["Schleiden","Newton"],"Schwann, in 1839."),
  mcq("s2-5",2,"Coloured plastids are called","chromoplasts",["nucleoids","ribosomes"],"Chroma means colour."),
  tf("s2-6",2,"The body grows only because cells get bigger.",False,"Growth is mainly because cells divide."),
  short("s2-7",3,"What is the region of genetic material in a prokaryotic cell called?",["nucleoid"],"The nucleoid."),
  mcq("s2-8",3,"A cut heals because cells","divide to replace damaged cells",["shrink","stop working"],"Cell division repairs tissue.")])
B(3,'Plant and animal tissues','Tissues in plants and animals and the musculoskeletal system','Teamwork of cells',
 "A football team needs players with different jobs. In a body, cells with the same job form a tissue. Plants and animals use different tissues because plants stay fixed while animals move.",
 [("A tissue is a group of similar cells that together perform a specific function.","tissue"),
  ("Plants are fixed and need support, so their cells have walls and many tissues give strength. Animals move, so they need muscles and bones.","plants and animals differ"),
  ("Plants grow at the tips of roots and shoots by apical meristem, which makes them longer.","apical meristem"),
  ("Lateral meristem makes plants grow in girth, becoming thicker, and intercalary meristem helps grass grow again after grazing.","lateral and intercalary meristem"),
  ("Permanent tissues include parenchyma (thin walls), collenchyma (unevenly thickened corners) and sclerenchyma, and the conducting tissues xylem and phloem.","permanent tissues"),
  ("In animals the main tissues are epithelial, connective, muscular and nervous. The cells of nervous tissue are called neurons.","animal tissues"),
  ("The musculoskeletal system is made of bones, muscles, joints, cartilage, tendons and ligaments. Muscles pull on bones, attached by tendons, to produce movement.","musculoskeletal system"),
  ("Joints let bones move: ball and socket at the shoulder, pivot, hinge and fixed joints. The skeleton, with skull, backbone and rib cage, protects organs.","joints and skeleton")],
 ("Which tissue makes a root grow longer and which makes a stem thicker?",[("Growth in length takes place at the tips: apical meristem.","Roots and shoots tips."),("Growth in girth happens by lateral meristem.","Side growth."),("So apical for length and lateral for thickness.","Match growth to meristem.")]),
 ("Name three plant tissues and two animal tissues with one function each.",["Meristem for growth","Xylem and phloem conduct","Muscle moves bones; nerve carries signals"],["Mixing up tendons and ligaments"]),
 ["Tissues are groups of cells with a common function.","Meristems cause growth in plants.","Animals have epithelial, connective, muscular and nervous tissues.","Bones, muscles and joints work together for movement."],
 [mcq("s3-1",1,"Growth in the length of a root happens through","apical meristem",["lateral meristem","xylem"],"Growth at the tip."),
  mcq("s3-2",1,"The shoulder is a","ball and socket joint",["hinge joint","fixed joint"],"It allows free movement."),
  tf("s3-3",1,"Tendons join muscles to bones.",True,"Tendons attach muscles to bones."),
  mcq("s3-4",2,"Cells of nervous tissue are called","neurons",["xylem","stomata"],"Neurons transmit signals."),
  mcq("s3-5",2,"Parenchyma consists of","living cells with thin walls",["dead cells with thick walls","only fibres"],"That is the definition."),
  tf("s3-6",2,"Grass regrows after grazing because of intercalary meristem.",True,"Intercalary meristem allows regrowth."),
  short("s3-7",3,"The backbone is made of small bones called",["vertebrae"],"Vertebrae form the backbone."),
  mcq("s3-8",3,"Which tissue conducts water in plants?","xylem",["phloem","collenchyma"],"Xylem carries water.")])
B(4,'Motion in a line and in a plane','Describing motion: velocity, acceleration and equations of motion','How fast, how far, how soon',
 "A swimmer in a race, a car on a straight highway, a ball dropped from a tower: all move in a straight line. We describe such motion with a few numbers, and those numbers can predict where the object will be.",
 [("Motion along a straight line is called linear motion, the simplest kind of motion.","linear motion"),
  ("Speed is distance travelled per unit time. Velocity is displacement per unit time and also has a direction.","speed and velocity"),
  ("Acceleration is the rate of change of velocity: a = (v - u)/t, where u is initial velocity, v final velocity and t the time.","a = (v - u)/t"),
  ("For constant acceleration the first equation of motion is v = u + a t.","v = u + at"),
  ("The second equation gives displacement: s = u t + 1/2 a t^2, and the third is v^2 = u^2 + 2 a s.","s = ut + 1/2 at^2; v^2 = u^2 + 2as"),
  ("From the area of a trapezium under the velocity-time graph we also get s = (u + v)t / 2.","s = (u + v)t/2"),
  ("Graphs help: the slope of a distance-time graph is the speed and the slope of a velocity-time graph is the acceleration.","slope of graphs"),
  ("Motion in a plane, like a kicked ball or a satellite, needs two directions. Motion along a circle is called circular motion.","motion in a plane")],
 ("A car starts from rest and accelerates at 2 m/s^2 for 5 s. Find its final velocity and distance.",[("u = 0, a = 2, t = 5, so v = 0 + 2 x 5 = 10 m/s.","Use v = u + at."),("s = 0 + 1/2 x 2 x 25 = 25 m.","Use s = ut + 1/2 at^2."),("Check: v^2 = 100 and 2as = 100.","Third equation agrees.")]),
 ("State the three equations of motion and what each symbol means.",["v = u + at","s = ut + 1/2 at^2","v^2 = u^2 + 2as"],["Mixing speed with velocity"]),
 ["Velocity includes direction; acceleration is the rate of change of velocity.","The equations of motion apply for constant acceleration.","Graph slopes give speed or acceleration.","Motion in a plane uses two directions."],
 [mcq("s4-1",1,"Acceleration is the rate of change of","velocity",["distance","mass"],"a = (v - u)/t."),
  mcq("s4-2",1,"The first equation of motion is","v = u + at",["s = vt","F = ma"],"Standard form."),
  tf("s4-3",1,"Velocity has both magnitude and direction.",True,"It is a vector."),
  num("s4-4",2,"A car with u = 0 and a = 2 m/s^2 moves for 5 s. v (m/s)?",10,"v = 2 x 5.",[(7,"Multiply, do not add.")]),
  num("s4-5",2,"Distance in the same 5 s (m)",25,"1/2 x 2 x 25.",[(50,"Do not forget the 1/2.")]),
  num("s4-6",2,"A ball is dropped (u = 0) with a = 10 m/s^2 for 2 s. Distance (m)?",20,"1/2 x 10 x 4 = 20.",[(40,"Use 1/2 a t^2.")]),
  mcq("s4-7",3,"The slope of a velocity-time graph gives","acceleration",["distance","mass"],"Slope is change in velocity over time."),
  short("s4-8",3,"Motion along a circular path is called ___ motion",["circular"],"Circular motion.")])
B(5,'Mixtures and their separation','Mixtures, solutions, separation methods and the Tyndall effect','Sugar in tea',
 "A sip of sweet tea is equally sweet from top to bottom, but muddy water separates into sand and water. Mixtures come in different kinds, and we separate them by different methods.",
 [("A mixture with uniform composition throughout is called a homogeneous mixture, or a solution. Examples are sugar in water, vinegar and soda.","homogeneous mixture"),
  ("A mixture in which the composition is not uniform is heterogeneous, such as sand in water or oil and water.","heterogeneous mixture"),
  ("In a solution, the substance that dissolves is the solute and the substance in which it dissolves is the solvent. Concentration tells the amount of solute in a given amount of solution.","solute, solvent"),
  ("A saturated solution cannot dissolve more solute at that temperature. Solubility is the amount of solute that dissolves in 100 g of solvent to make a saturated solution.","saturated solution, solubility"),
  ("Crystallisation separates a dissolved solid: cooling a hot saturated solution makes solute crystals form.","crystallisation"),
  ("Two immiscible liquids, like oil and water, are separated with a separating funnel; miscible liquids with different boiling points are separated by distillation.","separating funnel, distillation"),
  ("Chromatography separates coloured components of a mixture, like the dyes in ink or a food colour.","chromatography"),
  ("The Tyndall effect is the scattering of light by particles, which makes a light beam visible in colloids and suspensions but not in true solutions.","Tyndall effect")],
 ("How would you separate a mixture of salt and sand, and then recover the salt?",[("Add water; salt dissolves, sand does not.","Dissolve."),("Filter to remove the sand.","Filtration."),("Evaporate or crystallise the filtrate to obtain the salt.","Recover the solute.")]),
 ("Name three separation methods and the mixtures they suit.",["Crystallisation for dissolved solids","Distillation for miscible liquids","Chromatography for dyes"],["Thinking all mixtures are separated by filtration"]),
 ["Homogeneous mixtures are solutions; heterogeneous ones are not uniform.","Solute dissolves in solvent; saturated solutions hold no more solute.","Different mixtures need different separation methods.","The Tyndall effect shows scattering in colloids and suspensions."],
 [mcq("s5-1",1,"Sugar dissolved in water forms a","homogeneous mixture",["heterogeneous mixture","pure substance"],"Uniform composition."),
  mcq("s5-2",1,"Oil and water are separated by","a separating funnel",["evaporation","crystallisation"],"They are immiscible."),
  tf("s5-3",1,"The path of a light beam is visible in a true solution.",False,"The particles are too small to scatter light."),
  mcq("s5-4",2,"Two miscible liquids with different boiling points are separated by","distillation",["filtration","sedimentation"],"Different boiling points."),
  mcq("s5-5",2,"In salt solution, salt is the","solute",["solvent","colloid"],"The dissolved substance."),
  tf("s5-6",2,"A saturated solution can dissolve more solute at the same temperature.",False,"That is what saturated means."),
  short("s5-7",3,"Which technique separates the dyes in an ink? (one word)",["chromatography"],"Chromatography."),
  mcq("s5-8",3,"Cooling a hot saturated solution gives crystals. This is","crystallisation",["distillation","filtration"],"Solute crystallises out.")])
B(6,"Forces and Newton's laws",'Force, friction and Newton\'s three laws of motion','Push, pull and motion',
 "Why does a ball roll to a stop on the ground but keep going in space? The answer is force, and Newton's three laws explain exactly how forces change motion.",
 [("A force is a push or a pull. Balanced forces cancel and the net force is zero; unbalanced forces change an object's motion.","balanced and unbalanced forces"),
  ("Friction is the force that opposes relative motion between surfaces in contact. It is often useful, but also wastes energy as heat.","friction"),
  ("Newton's first law says an object stays at rest or in uniform motion in a straight line unless an unbalanced force acts on it. This property is called inertia.","first law and inertia"),
  ("Newton's second law says the net force is mass times acceleration, F = m a, so the same force gives a smaller acceleration to a larger mass.","F = ma"),
  ("The SI unit of force is the newton: 1 N = 1 kg m/s^2.","newton"),
  ("Newton's third law says that for every action there is an equal and opposite reaction, acting on different objects.","action and reaction"),
  ("When we study a system of objects, we find the net external force on the whole system and then use F = ma for the system.","system of objects"),
  ("Momentum is mass times velocity, and the change in momentum depends on the net force and the time it acts.","momentum")],
 ("A force of 20 N acts on a 4 kg trolley on a smooth floor. Find the acceleration.",[("Net force F = 20 N and mass m = 4 kg.","Read the data."),("a = F/m = 20/4.","Use F = ma."),("a = 5 m/s^2.","State with unit.")]),
 ("State Newton's three laws with an everyday example for each.",["Inertia (passenger jerks forward)","F = ma","Action and reaction on different bodies"],["Thinking action and reaction cancel because they act on the same body"]),
 ["Unbalanced force changes motion.","Friction opposes motion.","F = ma gives acceleration; 1 N = 1 kg m/s^2.","Action and reaction act on different objects."],
 [mcq("s6-1",1,"Inertia is the tendency of a body to","resist change in its state of motion",["move faster","lose mass"],"First law."),
  mcq("s6-2",1,"The SI unit of force is","newton",["joule","watt"],"Named after Newton."),
  tf("s6-3",1,"Action and reaction forces act on the same object.",False,"They act on different objects."),
  num("s6-4",2,"A 20 N force acts on a 4 kg mass. Acceleration (m/s^2)?",5,"20/4.",[(80,"Divide force by mass.")]),
  num("s6-5",2,"Force (N) needed to give 3 m/s^2 to a 5 kg mass",15,"5 x 3.",[(8,"Multiply mass and acceleration.")]),
  mcq("s6-6",2,"A passenger lurches forward when a bus brakes. This shows","inertia",["gravity","friction"],"The body continues in motion."),
  short("s6-7",3,"Which force opposes the relative motion of two surfaces? (one word)",["friction"],"Friction."),
  tf("s6-8",3,"Balanced forces change the motion of an object.",False,"Balanced forces give zero net force.")])
